class Solution {
  public int guessMajority(ArrayReader reader) {
    int n = reader.length();
    // swapping one index into a 4-query keeps the answer exactly when the two values are equal
    int base = reader.query(0, 1, 2, 3), base4 = reader.query(1, 2, 3, 4);
    int same = 1, diff = 0, diffIndex = -1; // relative to nums[0]
    if (base4 == base) same++;
    else {
      diff++;
      diffIndex = 4;
    }
    for (int i = 5; i < n; i++) {
      if (reader.query(1, 2, 3, i) == base) same++;
      else {
        diff++;
        diffIndex = i;
      }
    }
    int[][] probes = {{0, 2, 3, 4}, {0, 1, 3, 4}, {0, 1, 2, 4}}; // index 1, 2, 3 swapped out for index 0
    for (int k = 0; k < 3; k++) {
      if (reader.query(probes[k][0], probes[k][1], probes[k][2], probes[k][3]) == base4) same++;
      else {
        diff++;
        diffIndex = k + 1;
      }
    }
    if (same > diff) return 0;
    if (diff > same) return diffIndex;
    return -1;
  }
}
